pub trait ProfileHandler: Send + Sync + 'static {
    fn echo(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: AllTypes,
    ) -> ::cellar::sdk::rpc::HandlerFuture<AllTypes>;

    fn ping(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: (),
    ) -> ::cellar::sdk::rpc::HandlerFuture<()>;

    fn echo_child(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: all_types::Child,
    ) -> ::cellar::sdk::rpc::HandlerFuture<all_types::Child>;

    fn echo_timestamp(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: ::cellar::sdk::rpc::prost_types::Timestamp,
    ) -> ::cellar::sdk::rpc::HandlerFuture<::cellar::sdk::rpc::prost_types::Timestamp>;

    fn echo_duration(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: ::cellar::sdk::rpc::prost_types::Duration,
    ) -> ::cellar::sdk::rpc::HandlerFuture<::cellar::sdk::rpc::prost_types::Duration>;

    fn echo_mappings(
        self: ::std::sync::Arc<Self>,
        context: ::cellar::sdk::Context,
        request: RuntimeMappings,
    ) -> ::cellar::sdk::rpc::HandlerFuture<RuntimeMappings>;
}

